import{_ as t}from"./chunks/architecture.DdIdPF_l.js";import{_ as a,o as i,c as s,a6 as r}from"./chunks/framework.CKIbuWFA.js";const g=JSON.parse('{"title":"Application and service architecture","description":"","frontmatter":{"title":"Application and service architecture","docId":"developer.architecture","translationKey":"developer.architecture","locale":"en","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"00ea88ebd11714484d717b7d7533d29158afd498121db362a3d300bc21889501","translationRevision":"00ea88ebd11714484d717b7d7533d29158afd498121db362a3d300bc21889501","order":30},"headers":[],"relativePath":"en/developer/architecture.md","filePath":"en/developer/architecture.md","lastUpdated":1794611623000}'),o={name:"en/developer/architecture.md"};function n(c,e,d,l,h,p){return i(),s("div",null,[...e[0]||(e[0]=[r(`<h1 id="application-and-service-architecture" tabindex="-1">Application and service architecture <a class="header-anchor" href="#application-and-service-architecture" aria-label="Permalink to &quot;Application and service architecture {#application-and-service-architecture}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Goal and prerequisites <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Goal and prerequisites {#goal-and-prerequisites}&quot;">​</a></h2><p>Place a change in the service that owns its state. Read <a href="./setup.html">setup</a> and understand the difference between an existing host and an explicit standalone host. The desktop constructs one <code>AppCore</code>, wraps it in one <code>ControlApi</code> and exposes that instance to the WebView, local CLI and agents.</p><h2 id="trace-an-operation" tabindex="-1">Trace an operation <a class="header-anchor" href="#trace-an-operation" aria-label="Permalink to &quot;Trace an operation {#trace-an-operation}&quot;">​</a></h2><ol><li>Find the method&#39;s registration in <code>crates/tiktools-control-api/src/modules/</code>. Registration supplies schemas, policy and discovery metadata.</li><li>Follow the handler into <code>crates/tiktools-core/src/control/</code> and the owning service. Put domain validation and persistent mutations here rather than in a transport adapter.</li><li>Add the typed wrapper in <code>crates/tiktools-client</code>; its parity test compares SDK coverage with the registered surface.</li><li>Consume the method through <code>src/web/shared/api/control-client.ts</code>. Vue entities hold presentation state; the desktop does not hand the WebView a database or native integration object.</li></ol><p>Winit owns the event loop, Wry the WebView and the tray integration the tray. <code>HostEmitter</code> and domain events carry serialized values out of core. The desktop forwards work through its event-loop proxy; WebView script evaluation stays on that thread. Tokio runs asynchronous host operations.</p><h2 id="concrete-boundary-check" tabindex="-1">Concrete boundary check <a class="header-anchor" href="#concrete-boundary-check" aria-label="Permalink to &quot;Concrete boundary check {#concrete-boundary-check}&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> control-client</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rust</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tiktools-client</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> parity</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span></span></code></pre></div><p>The first command checks the frontend client. The second runs the SDK integration target directly while preserving the lockfile; Cargo target flags belong on the <code>rust</code> passthrough rather than the narrower targeted-test grammar.</p><h2 id="expected-result-and-status" tabindex="-1">Expected result and status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Expected result and status {#expected-result-and-status}&quot;">​</a></h2><p>All clients observe the same authoritative operation and event path. <code>host --ipc</code>, <code>host --stdio</code> and <code>--standalone</code> intentionally create headless ownership; normal CLI commands attach to a running owner. The legacy <code>PageMessage</code>/<code>IpcRouter</code> path remains compatibility code and should not gain new message variants.</p><h2 id="recovery" tabindex="-1">Recovery <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recovery {#recovery}&quot;">​</a></h2><p>If two clients disagree, compare host identity, home directory, build features and discovery before adding another store. A missing plugin is a runtime catalog issue, not a reason to compile its implementation into core. Historical architecture documents contain retired frontend paths; follow the <a href="https://github.com/nglmercer/TikTools-app/blob/remake/crates/tiktools-core/src/lib.rs" target="_blank" rel="noreferrer">current core</a> and <a href="./frontend.html">frontend map</a> when they differ.</p><p><img src="`+t+'" alt="TikTools AppCore, transport, ControlClient and real Vue workspace"></p><h2 id="operational-details" tabindex="-1">Operational details <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Operational details {#operational-details}&quot;">​</a></h2><p>The selected binary’s Cargo features determine compiled paths. Core defaults enable <code>native-plugins</code> and <code>napi-vm-node-api</code>; <code>persistence</code> supplies SQLite services, <code>native-tiktok</code> the LIVE adapter/ingress, and <code>plugin-install</code>, <code>cloud-auth</code>, <code>app-update</code> add their respective services. Inspect <code>cargo tree -p tiktools-desktop -e features</code> (or the actual CLI target), then runtime <code>system.info</code>/discovery. Compiled support does not establish configured service availability. Exercise LIVE ingress explicitly with the <code>native-tiktok</code> regression in <a href="./performance.html">performance</a>.</p>',16)])])}const m=a(o,[["render",n]]);export{g as __pageData,m as default};
